{"content": "import csv

def parse_csv(file_path):
    """
    Parse CSV file into a list of dictionaries.
    Converts numeric strings to floats, handles missing values.
    """
    with open(file_path) as f:
        reader = csv.DictReader(f)
        result = []
        for row in reader:
            parsed_row = {}
            for key, value in row.items():
                parsed_value = parse_value(value)
                if parsed_value is not None:
                    parsed_row[key] = parsed_value
            result.append(parsed_row)
    return result

def parse_value(value):
    """Handle value parsing with type conversion and NA handling"""
    if value is None:
        return None
    try:
        return float(value)
    except ValueError:
        pass
    # Handle empty strings as missing values
    if isinstance(value, str) and not value.strip():
        return None
    # Handle "NA" strings as missing values
    if value == "NA":
        return None
    return value", "line_count": 28}

