	if weather.TempC != 15.5 {
		t.Errorf("expected temp 15.5, got %v", weather.TempC)
	}
	if weather.Condition != "Partly cloudy" {
		t.Errorf("expected condition 'Partly cloudy', got %q", weather.Condition)
