const https = require('https');

function fetchUser(id, cb) {
  https.get(`https://api.example.com/users/${id}`, (res) => {
    let data = '';
    res.on('data', (chunk) => { data += chunk; });
    res.on('end', () => {
      if (res.statusCode === 200) {
        try {
          const user = JSON.parse(data);
          cb(null, user);
        } catch (err) {
          cb(err);
        }
      } else if (res.statusCode === 404) {
        cb({ code: 404, message: 'User not found' });
      } else {
        cb(new Error(`HTTP ${res.statusCode}`));
      }
    });
  }).on('error', (err) => {
    cb(err);
  });
}

function fetchAllUsers(ids, cb) {
  const users = [];
  let index = 0;
  function next() {
    if (index >= ids.length) return cb(null, users);
    fetchUser(ids[index], (err, user) => {
      if (err) return cb(err);
      users.push(user);
      index++;
      next();
    });
  }
  next();
}

module.exports = { fetchUser, fetchAllUsers };

