export class ApiError extends Error { constructor(public status: number, message: string) { super(message); this.name = 'ApiError'; } }

const BASE_URL = 'https://api.github.com';

async function request<T>(path: string, options: RequestInit = {}): Promise<T> {
  const response = await fetch(BASE_URL + path, {
    ...options,
    headers: {
      'Accept': 'application/vnd.github+json',
      ...options.headers
    }
  });

  if (!response.ok) {
    const errorBody = await response.json().catch(() => ({ message: response.statusText }));
    throw new ApiError(response.status, errorBody.message || 'Unknown error');
  }

  return response.json() as Promise<T>;
}

export class GitHubClient {
  constructor(private token: string | null = null) {}

  async getRepository(owner: string, repo: string): Promise<Repository> {
    return request<Repository>(`/repos/${owner}/${repo}`);
  }

  async createIssue(owner: string, repo: string, data: CreateIssueRequest): Promise<Issue> {
    return request<Issue>(`/repos/${owner}/${repo}/issues`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(this.token ? { Authorization: `Bearer ${this.token}` } : {})
      },
      body: JSON.stringify(data)
    });
  }
}
