const express = require('express');
const app = express();
app.use(express.json());

const sessions = new Map();

function detectIntent(message) {
  const lower = message.toLowerCase();
  if (/order|track|status|where is|shipping/.test(lower)) return 'order_status';
  return 'other';
}

function extractOrderId(message) {
  const match = message.match(/order\s*#?([A-Za-z0-9]+)/i);
  return match ? match[1] : null;
}

async function fetchOrderStatus(orderId) {
  // Mock implementation; replace with actual HTTP call.
  if (orderId === '12345') {
    return { status: 'shipped', tracking_number: 'TRACK123' };
  }
  const err = new Error('Not found');
  err.status = 404;
  throw err;
}

app.post('/webhook', async (req, res) => {
  const { session_id, message } = req.body;
  if (!session_id || !message) {
    return res.status(400).json({ reply: 'Missing session_id or message.' });
  }

  let state = sessions.get(session_id) || { intent: 'other', order_id: null, last_reply: '' };
  const intent = detectIntent(message);

  if (intent === 'order_status') {
    let orderId = extractOrderId(message) || state.order_id;
    if (!orderId) {
      const reply = 'Please provide your order ID.';
      state = { intent: 'order_status', order_id: null, last_reply: reply };
      sessions.set(session_id, state);
      return res.json({ reply });
    }

    try {
      const order = await fetchOrderStatus(orderId);
      const reply = `Your order ${orderId} is ${order.status}. Tracking number: ${order.tracking_number}.`;
      state = { intent: 'order_status', order_id: orderId, last_reply: reply };
      sessions.set(session_id, state);
      return res.json({ reply });
    } catch (err) {
      const reply = err.status === 404 ? 'Order not found. Please check your order ID.' : 'Sorry, I encountered an error. Please try again.';
      state = { intent: err.status === 404 ? 'order_status' : 'other', order_id: err.status === 404 ? orderId : null, last_reply: reply };
      sessions.set(session_id, state);
      return res.json({ reply });
    }
  } else {
    const reply = 'I can help with order status. Please provide your order ID.';
    state = { intent: 'other', order_id: null, last_reply: reply };
    sessions.set(session_id, state);
    return res.json({ reply });
  }
});

