{"file_path": "core.py", "content": "import csv
from statistics import mean

def compute_stats(file_path, summary=False):
    with open(file_path, newline='') as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None:
            raise ValueError("File is empty or has no columns")
        rows = list(reader)
    if not rows and not reader.fieldnames:
        raise ValueError("File is empty or has no columns")
    if summary:
        return {"row_count": len(rows), "column_count": len(reader.fieldnames)}
    stats = {}
    for col in reader.fieldnames:
        values = [row[col] for row in rows if row[col] != '']
        if not values:
            stats[col] = {"count": 0}
        else:
            try:
                nums = [float(v) for v in values]
                stats[col] = {"mean": mean(nums), "min": min(nums), "max": max(nums), "count": len(nums)}
            except ValueError:
                uniq = set(values)
                mode = max(set(values), key=values.count)
                stats[col] = {"unique_values": len(uniq), "mode": mode}
    return stats
"}

