{"file_path": "webhook_handler.py", "content": "import json
import requests
from flask import Flask, request, jsonify

app = Flask(__name__)

EXTERNAL_API = "https://api.example.com/chat"
API_TOKEN = "abc123"
TIMEOUT = 5  # seconds

@app.route("/webhook", methods=["POST"])
def webhook():
    data = request.get_json(silent=True)
    if data is None:
        return jsonify({"error": "invalid_json"}), 400

    session_id = data.get("session_id")
    message = data.get("message")
    user_id = data.get("user_id")

    # Validate fields
    if not isinstance(session_id, str) or not isinstance(message, str) or not isinstance(user_id, int):
        return jsonify({"error": "invalid_fields"}), 400

    try:
        resp = requests.post(
            EXTERNAL_API,
            json={"session_id": session_id, "message": message},
            headers={"Authorization": f"Bearer {API_TOKEN}"},
            timeout=TIMEOUT
        )
    except requests.exceptions.Timeout:
        return jsonify({"error": "timeout"}), 504
    except requests.exceptions.RequestException as e:
        # For other connection errors, return 502
        return jsonify({"error": "upstream_error"}), 502

    if resp.status_code != 200:
        return jsonify({"error": "upstream_error"}), 502

    try:
        reply = resp.json().get("reply")
    except (json.JSONDecodeError, AttributeError):
        return jsonify({"error": "invalid_response"}), 502

    if not isinstance(reply, str):
        return jsonify({"error": "invalid_response"}), 502

    return jsonify({"reply": reply}), 200

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
"}

